import json
from pathlib import Path

base = Path(__file__).resolve().parent
rows = json.loads((base / 'tip-review-input-COS201.json').read_text(encoding='utf-8-sig'))
changes = {}
why = {}

def keep(ids, rationale):
    for n in ids:
        why[f'COS201-{n}'] = rationale

def fix(ids, tip, rationale, reason=None, references=None):
    for n in ids:
        id = f'COS201-{n}'
        entry = dict(id=id, tip=tip, whyVi=rationale)
        if reason:
            entry['reason'] = reason
        if references:
            entry['references'] = references
        changes[id] = entry
        why[id] = rationale

