ids = [r['id'] for r in rows]
assert len(ids) == 214 and len(set(ids)) == 214
assert set(why) == set(ids), ('missing', set(ids)-set(why), 'extra', set(why)-set(ids))
for id, c in changes.items():
    assert 20 <= len(c['tip']) <= 180, (id, len(c['tip']))
    assert c['tip'] != next(r['tip'] for r in rows if r['id'] == id)
out = {
    'subject': 'COS201',
    'reviewedCount': len(rows),
    'ledger': [dict(id=id, status='fix' if id in changes else 'keep', whyVi=why[id]) for id in ids],
    'changes': [changes[id] for id in ids if id in changes],
}
(base / 'tip-review-COS201.json').write_text(json.dumps(out, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
